/* Job context — keeps the role an applicant came from attached to them across
   the whole auth flow, whether they sign up or log in.
 *
 * Load AFTER /assets/js/jobs-index.js (generated by scripts/build-jobs.mjs),
 * which provides window.DEFRILEX_JOBS for resolving an id to a title/slug.
 *
 * Behaviour:
 *   - Reads ?job=<ID> from the URL; if absent, falls back to the id saved
 *     earlier in the session. So /login -> "Forgot password?" -> back to
 *     /login keeps the role even though the param was dropped along the way.
 *   - Fills the #applyBanner block, when the page has one.
 *   - Sets the #jobInput hidden field, when the page has one.
 *   - Rewrites links to the other auth pages (and to the marketplace app's
 *     login/register) so the id survives every hop.
 *
 * The id is user-controlled: it is validated against a strict pattern, only
 * ever written to the DOM with textContent, and never used to build a path.
 */
(function () {
  var KEY = 'defrilex:job';
  var VALID = /^[A-Za-z0-9_-]{1,40}$/;

  // Same-origin pages that are part of the apply/auth journey. Both naming
  // conventions are listed: defrilex-ls uses /login + /register, defrilexcx
  // ships /signin + /signup, and the Laravel app routes /login + /register.
  // Covering all of them means the id survives whichever set is actually live.
  var AUTH_PATHS = [
    '/login', '/register',
    '/signin', '/signup',
    '/forgot-password', '/reset-password', '/code-verify'
  ];
  // The marketplace app, when apply/sign-in points there instead of a local page.
  var APP_HOSTS = ['app.defrilex-ls.com', 'app.defrilexcx.com'];
  var APP_PATHS = ['/login', '/register', '/signin', '/signup'];

  function readParam() {
    try {
      return new URLSearchParams(window.location.search).get('job');
    } catch (e) {
      return null;
    }
  }

  function save(id) {
    try {
      window.sessionStorage.setItem(KEY, id);
    } catch (e) {
      /* private mode / storage disabled — the URL param still works */
    }
  }

  function recall() {
    try {
      return window.sessionStorage.getItem(KEY);
    } catch (e) {
      return null;
    }
  }

  var id = readParam();
  if (id) {
    save(id);
  } else {
    id = recall();
  }
  if (!id || !VALID.test(id)) return;

  var known = (window.DEFRILEX_JOBS || {})[id] || null;

  /* ---- 1. banner ---- */
  var banner = document.getElementById('applyBanner');
  if (banner) {
    var titleEl = document.getElementById('applyBannerTitle');
    var idEl = document.getElementById('applyBannerId');
    var linkEl = document.getElementById('applyBannerLink');

    if (idEl) idEl.textContent = id;
    if (titleEl) titleEl.textContent = known ? known.title : 'This role';
    if (linkEl) {
      // Destination comes from the generated index, never from the URL.
      if (known) {
        linkEl.href = '/jobs/' + known.slug;
      } else {
        linkEl.href = '/talent#openings';
        linkEl.textContent = 'Browse open roles';
      }
    }
    banner.hidden = false;
  }

  /* ---- 2. hidden field, so the id posts with the form ---- */
  var input = document.getElementById('jobInput');
  if (input) input.value = id;

  /* ---- 3. keep the id on every onward auth hop ---- */
  function shouldCarry(url) {
    if (url.origin === window.location.origin) {
      var path = url.pathname.replace(/\.html$/, '').replace(/\/$/, '') || '/';
      return AUTH_PATHS.indexOf(path) !== -1;
    }
    if (APP_HOSTS.indexOf(url.hostname) !== -1) {
      var appPath = url.pathname.replace(/\/$/, '') || '/';
      return APP_PATHS.indexOf(appPath) !== -1;
    }
    return false;
  }

  var anchors = document.querySelectorAll('a[href]');
  for (var i = 0; i < anchors.length; i++) {
    var a = anchors[i];
    var raw = a.getAttribute('href');
    if (!raw || raw.charAt(0) === '#') continue;

    var url;
    try {
      url = new URL(a.href, window.location.href);
    } catch (e) {
      continue;
    }
    if (!shouldCarry(url)) continue;
    if (url.searchParams.get('job') === id) continue;

    url.searchParams.set('job', id);
    a.href = url.toString();
  }

  window.DefrilexJobContext = {
    id: id,
    job: known,
    clear: function () {
      try {
        window.sessionStorage.removeItem(KEY);
      } catch (e) {
        /* nothing to clear */
      }
    }
  };
})();
